// Dependency-free SVG views. Values are derived elsewhere; never reads storage.
const ChartView = (() => {
 const history=typeof module!=='undefined'&&module.exports?require('./history.js'):History;
 const palette=['#253f50','#66858d','#baa074','#8b809b','#b87f86','#7d9c86','#727c8b','#a69b82'];
 const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const money=value=>new Intl.NumberFormat('th-TH',{minimumFractionDigits:2,maximumFractionDigits:2}).format(value)+' ฿';
 const percent=value=>new Intl.NumberFormat('th-TH',{maximumFractionDigits:1}).format(value)+'%';
 const range=w=>w.start===w.end?history.dateLabel(w.start,new Date(),true):Number(w.start.slice(8))+'–'+history.dateLabel(w.end,new Date(),true);
 const short=value=>{const unit=value>=1e9?1e9:value>=1e6?1e6:value>=1e3?1e3:1;return new Intl.NumberFormat('th-TH',{maximumFractionDigits:1}).format(value/unit)+(unit===1e9?'B':unit===1e6?'M':unit===1e3?'K':'')};
 function donut(source,income=false){
  const model=income?{categories:source.incomeCategories||[],expenseTotal:source.incomeTotal}:source;
  const label=income?'รายรับ':'รายจ่าย';
  const palette=income?['#365f50','#65947e','#a9af7c','#749b9e','#a19170','#8ba49c','#72918a','#b7b599']:['#253f50','#66858d','#baa074','#8b809b','#b87f86','#7d9c86','#727c8b','#a69b82'];
  if(!model.categories.length)return '<div class="chart-empty">ยังไม่มี'+label+'ในเดือนนี้</div>';
  const radius=84,circumference=2*Math.PI*radius;let offset=0;
  const tint=(hex,amount)=>'#'+hex.slice(1).match(/../g).map(v=>Math.max(0,Math.min(255,parseInt(v,16)+amount)).toString(16).padStart(2,'0')).join('');
  const defs=palette.map((color,i)=>'<linearGradient id="donutTone'+i+'" x1="0" y1="0" x2="1" y2="1"><stop stop-color="'+tint(color,28)+'"/><stop offset=".55" stop-color="'+color+'"/><stop offset="1" stop-color="'+tint(color,-12)+'"/></linearGradient>').join('');
  const rings=model.categories.map((c,index)=>{
   const raw=c.percentage/100*circumference,gap=model.categories.length>1?Math.min(5,raw*.12):0,length=raw-gap,angle=(offset+raw/2)/circumference*2*Math.PI-Math.PI/2;
   const label=c.name+' · '+money(c.amount)+' · '+percent(c.percentage);
   const svg='<g class="donut-piece" style="--slice-x:'+(Math.cos(angle)*4).toFixed(2)+'px;--slice-y:'+(Math.sin(angle)*4).toFixed(2)+'px"><circle class="donut-segment" cx="120" cy="120" r="84" fill="none" stroke="url(#donutTone'+index%palette.length+')" stroke-width="27" stroke-dasharray="'+length+' '+(circumference-length)+'" stroke-dashoffset="'+(-offset-gap/2)+'" transform="rotate(-90 120 120)" tabindex="0" role="button" aria-pressed="false" aria-controls="analyticsSelection" aria-label="'+esc(label)+'" data-chart-category="'+index+'"><title>'+esc(label)+'</title></circle></g>';
   offset+=raw;return svg;
  }).join('');
  return '<div class="donut-layout"><div class="donut-figure"><div class="donut-stage"><div class="donut-orbit"><svg class="donut-chart" viewBox="0 0 240 240" role="group" aria-label="สัดส่วน'+label+'ตามหมวด"><defs>'+defs+'</defs><circle class="donut-guide" cx="120" cy="120" r="110"/><circle class="donut-guide-inner" cx="120" cy="120" r="63"/>'+rings+'</svg></div><div class="donut-center-content" aria-hidden="true"><span id="donutCenterName"></span><strong id="donutCenterPercent"></strong><span id="donutCenterAmount"></span><small>ของ'+label+'ทั้งหมด</small></div></div><div class="donut-category-nav"><button type="button" data-chart-step="-1" aria-label="เลือกหมวดก่อนหน้า"><svg class="icon" aria-hidden="true"><use href="#i-chevron-right"/></svg></button><span id="donutPosition"></span><button type="button" data-chart-step="1" aria-label="เลือกหมวดถัดไป"><svg class="icon" aria-hidden="true"><use href="#i-chevron-right"/></svg></button></div><div class="donut-total-pill"><span>'+label+'รวม</span><strong>'+money(model.expenseTotal)+'</strong></div></div><div class="donut-list-panel"><p class="donut-list-heading">สัดส่วนตามหมวด <span>มาก → น้อย</span></p><div class="chart-category-list" role="group" aria-label="เลือกหมวดเพื่อดูยอดเต็ม">'+model.categories.map((c,index)=>'<button type="button" class="chart-category" style="--category-color:'+palette[index%palette.length]+'" data-chart-category="'+index+'" aria-pressed="false" aria-controls="analyticsSelection"><span class="chart-swatch" style="background:'+palette[index%palette.length]+'" aria-hidden="true">'+(index+1)+'</span><span class="chart-category-copy"><span>'+esc(c.name)+'</span><small>'+percent(c.percentage)+'</small><span class="category-track" aria-hidden="true"><i style="width:'+c.percentage+'%;background:'+palette[index%palette.length]+'"></i></span></span><b>'+money(c.amount)+'</b></button>').join('')+'</div></div></div><div id="analyticsSelection" class="chart-selection" role="status"></div>';
 }
 function bars(model){
  const maximum=Math.max(0,...model.weeks.flatMap(w=>[w.income,w.expense]));
  if(!maximum)return '<div class="chart-empty">ยังไม่มีรายรับหรือรายจ่ายในเดือนนี้</div>';
  const left=44,baseline=174,height=130,plotWidth=302,step=plotWidth/model.weeks.length,barWidth=Math.min(17,(step-12)/2);
  const ticks=[0,maximum/2,maximum].map(n=>{const y=baseline-n/maximum*height;return '<line x1="'+left+'" x2="350" y1="'+y+'" y2="'+y+'" class="chart-gridline"/><text x="37" y="'+(y+4)+'" text-anchor="end" class="chart-axis">'+short(n)+'</text>'}).join('');
  const columns=model.weeks.map((w,index)=>{const center=left+step*(index+.5),label='สัปดาห์ที่ '+(index+1)+' · '+range(w)+' · รับ '+money(w.income)+' จ่าย '+money(w.expense)+' สุทธิ '+money(w.net);return '<g class="chart-week" tabindex="0" role="button" aria-pressed="false" aria-controls="analyticsWeekSelection" aria-label="'+esc(label)+'" data-chart-week="'+index+'"><title>'+esc(label)+'</title><rect class="chart-hit-area" x="'+(left+step*index)+'" y="24" width="'+step+'" height="196" rx="9" fill="transparent"/><rect class="chart-bar-income" x="'+(center-barWidth-2)+'" y="'+(baseline-w.income/maximum*height)+'" width="'+barWidth+'" height="'+(w.income/maximum*height)+'" rx="4"/><rect class="chart-bar-expense" x="'+(center+2)+'" y="'+(baseline-w.expense/maximum*height)+'" width="'+barWidth+'" height="'+(w.expense/maximum*height)+'" fill="url(#analyticsExpensePattern)" rx="2"/><text x="'+center+'" y="198" text-anchor="middle" class="chart-axis chart-week-label">ส.'+(index+1)+'</text><text x="'+center+'" y="215" text-anchor="middle" class="chart-date-label">'+Number(w.start.slice(8))+'–'+Number(w.end.slice(8))+'</text></g>'}).join('');
  return '<div class="chart-legend"><span><i class="chart-legend-income" aria-hidden="true"></i>รับ · แท่งซ้าย</span><span><i class="chart-legend-expense" aria-hidden="true"></i>จ่าย · แท่งขวา</span></div><svg class="weekly-bar-chart" viewBox="0 0 360 230" role="group" aria-label="เปรียบเทียบรายรับรายจ่ายแต่ละสัปดาห์"><defs><pattern id="analyticsExpensePattern" width="6" height="6" patternUnits="userSpaceOnUse"><rect width="6" height="6" class="chart-expense-base"/><path d="M-1 1 1-1 M0 6 6 0 M5 7 7 5" stroke="white" stroke-opacity=".28" stroke-width="1"/></pattern></defs>'+ticks+columns+'</svg><p class="chart-hint">แตะสัปดาห์เพื่อดูยอดเต็ม · K = พัน · M = ล้าน · B = พันล้าน</p><div id="analyticsWeekSelection" class="chart-selection" role="status"></div><details class="chart-data"><summary>ดูตัวเลขทุกสัปดาห์</summary><div class="chart-table-wrap"><table><caption class="sr-only">รายรับ รายจ่าย และสุทธิแต่ละสัปดาห์</caption><thead><tr><th scope="col">ช่วงวันที่</th><th scope="col">รับ</th><th scope="col">จ่าย</th><th scope="col">สุทธิ</th></tr></thead><tbody>'+model.weeks.map(w=>'<tr><th scope="row">'+esc(range(w))+'</th><td>'+money(w.income)+'</td><td>'+money(w.expense)+'</td><td>'+money(w.net)+'</td></tr>').join('')+'</tbody></table></div></details>';
 }

 function selection(kind,item,index){
  if(kind==='category')return '<div class="category-detail'+(item.amount>=100000?' has-long-values':'')+'"><span class="eyebrow">หมวดที่เลือก · '+percent(item.percentage)+'</span><strong>'+esc(item.name)+'</strong><b>'+money(item.amount)+'</b></div>';
  return '<div class="week-detail-heading"><strong>สัปดาห์ที่ '+(index+1)+'</strong><span>'+esc(range(item))+'</span></div><div class="chart-detail-totals'+(Math.max(item.income,item.expense,Math.abs(item.net))>=100000?' has-long-values':'')+'"><div><span>รายรับ</span><b class="chart-income-value">'+money(item.income)+'</b></div><div><span>รายจ่าย</span><b class="chart-expense-value">'+money(item.expense)+'</b></div><div><span>สุทธิ</span><b>'+money(item.net)+'</b></div></div>'+(item.net<0?'<small class="chart-net-explanation">จ่ายมากกว่ารับ '+money(-item.net)+' · ไม่ใช่ยอดเงินในบัญชี</small>':'');
 }
 function categoryPanel(model,income=false){
  const categories=income?model.incomeCategories||[]:model.categories;
  return '<div class="section-heading"><div><span class="eyebrow">'+(income?'INCOME BREAKDOWN':'EXPENSE BREAKDOWN')+'</span><h3 id="donutTitle">'+(income?'รายรับมาจากไหน':'เงินไปกับอะไร')+'</h3><p class="chart-subtitle">'+categories.length+' หมวด · แตะเพื่อดูรายละเอียด</p></div></div>'+donut(model,income);
 }
 function render(model){return '<div class="analytics-tabs" role="group" aria-label="เลือกกราฟ"><button type="button" data-analytics-view="categories" aria-pressed="true" aria-controls="analyticsCategories">รายจ่ายตามหมวด</button><button type="button" data-analytics-view="income" aria-pressed="false" aria-controls="analyticsCategories">รายรับตามหมวด</button><button type="button" data-analytics-view="weeks" aria-pressed="false" aria-controls="analyticsWeeks">รับ–จ่ายรายสัปดาห์</button></div><section id="analyticsCategories" class="analytics-section" aria-labelledby="donutTitle">'+categoryPanel(model)+'</section><section id="analyticsWeeks" class="analytics-section hidden" aria-labelledby="barChartTitle"><div class="section-heading"><div><span class="eyebrow">WEEKLY CASH FLOW</span><h3 id="barChartTitle">รับและจ่าย เทียบกันชัด ๆ</h3><p class="chart-subtitle">ทุกสัปดาห์ในเดือน · แตะแท่งเพื่อดูยอดเต็ม</p></div></div>'+bars(model)+'</section>'}
 return {render,categoryPanel,selection,money,percent,range};
})();
if(typeof module!=='undefined')module.exports=ChartView;
